do $release$ declare payload jsonb:='{"batch":"nl-scale-20261102-016","project":"hlvujbrmfdlrfxdjwsmb","actions":[{"ref":"e0","relation":"editions","key":{"id":987215001},"before":{"id":987215001,"title":"Gullivers reizen","isbn_10":"9027491259","isbn_13":null,"work_id":987115001,"cover_id":null,"language":"dut","publisher":"Het Spectrum","publish_date":null,"open_library_edition_id":"OL24354314M"},"after":{"id":987215001,"title":"Gullivers reizen","isbn_10":"9027491259","isbn_13":"9789027491251","work_id":987115001,"cover_id":null,"language":"dut","publisher":"Het Spectrum","publish_date":null,"open_library_edition_id":"OL24354314M"}},{"ref":"d0","relation":"catalog_work_descriptions","key":{"work_id":987115001,"language":"nl"},"before":null,"after":{"work_id":987115001,"language":"nl","bound_author_id":987315001,"text":"Lemuel Gulliver beschrijft reizen die hem telkens buiten zijn vertrouwde wereld brengen. Hij belandt onder meer tussen uitzonderlijk kleine mensen, in een rijk van reuzen en op een vliegend eiland. De gebruiken van deze samenlevingen dwingen hem zijn eigen maatstaven te herzien. Wat als een avontuurlijk reisverslag begint, wordt zo ook een onderzoek naar menselijke ijdelheid, macht en zogenaamd verstandige instellingen. Swift gebruikt de botsing tussen Gulliver en zijn gastheren als satire op zijn eigen samenleving.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.boekenplatform.nl/gullivers-reizen-63669","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p801594057"],"checked_at":"2026-11-02T21:24:43.768Z","reference":"work:1395","note":"Exact existing1979Spectrumhardcover, ArjaanvanNimwegen translation. KB binds original four-part title, exact translator and269p, distinct from abridged youth/first-two-parts editions. AuthorSwift, not translator. Reuse existing Work1395/edition1440 and fill only absent ISBN; no duplicate edition.","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-020.json","sources":["https://www.boekenplatform.nl/gullivers-reizen-63669","https://www.boekwinkeltjes.nl/v/lammegoedzak/page/67/?sort=nr0","https://openlibrary.org/works/OL20600W","https://data.bibliotheken.nl/id/nbt/p801594057"]},{"type":"cover_front_review","cover_id":6578724,"sha256":"0f49912a12a216377b7275f38ced33d2aec16fa766c65879f5217bd26d46e016","reference":"cover-semantic-review-010.json","limitation":"Actually read cover-large/sheet-002.jpg. Jonathan Swift; Gullivers reizen; Kramers Klassieken. Front identity and source-edition attachment are corroboration, not proof of a visible barcode, printing year, language or complete contents. Bibliographic checks remain separate."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-02T21:24:43.768Z","review_batch":"nl-scale-20261102-016"}},{"ref":"m0","relation":"catalog_edition_metadata","key":{"edition_id":987215001},"before":null,"after":{"edition_id":987215001,"work_id":987115001,"bound_author_id":987315001,"bound_title":"Gullivers reizen","bound_language":"dut","bound_isbn13":"9789027491251","format":"hardcover","cover_url":"https://covers.openlibrary.org/b/id/6578724-L.jpg?default=false","card_cover_url":"https://covers.openlibrary.org/b/id/6578724-M.jpg?default=false","evidence_url":"https://data.bibliotheken.nl/id/nbt/p801594057","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p801594057"],"checked_at":"2026-11-02T21:24:43.768Z","reference":"work:1395","note":"Exact existing1979Spectrumhardcover, ArjaanvanNimwegen translation. KB binds original four-part title, exact translator and269p, distinct from abridged youth/first-two-parts editions. AuthorSwift, not translator. Reuse existing Work1395/edition1440 and fill only absent ISBN; no duplicate edition.","canonical_name_resolution":null},{"type":"ori